    public function roster(string $username):array
    {
        $configured=(string)$this->settings->get('simulator_driver_names',implode("\n",self::DEFAULT_DRIVER_NAMES));$names=[];
        foreach(preg_split('/\R/u',$configured)?:[] as $name){$name=trim($name);if($name!==''&&strcasecmp($name,$username)!==0&&!in_array(strtolower($name),array_map('strtolower',$names),true))$names[]=$name;}
        if(count($names)<6)$names=self::DEFAULT_DRIVER_NAMES;
        shuffle($names);$drivers=[self::driver('self',$username,true)];
        for($i=0;$i<6;$i++)$drivers[]=self::driver('candidate-'.$i,$names[$i],false);
        return$drivers;
    }

    private static function driver(string $id,string $name,bool $required):array
    {
        return['id'=>$id,'name'=>$name,'required'=>$required,'endurance'=>random_int(45,95),'driving'=>random_int(45,95),'copilot'=>random_int(45,95)];
    }

    public static function locationName(string $node):string{return self::LOCATIONS[$node]??ucwords(str_replace('_',' ',$node));}
    public static function routeName(string $segment):string{$parts=explode('_to_',$segment,2);return count($parts)===2?self::locationName($parts[0]).' to '.self::locationName($parts[1]):$segment;}
    public static function routeLabel(array $segments):string
    {
        $nodes=[];
        foreach($segments as $segment){$parts=explode('_to_',(string)$segment,2);if(count($parts)!==2)continue;if(!$nodes)$nodes[]=$parts[0];$nodes[]=$parts[1];}
        return implode(' → ',array_map([self::class,'locationName'],$nodes));
    }

    public function cars():array{$rows=$this->pdo->query('SELECT id,name,mpg_below_35,mpg_35_70,mpg_above_70,capacity,top_speed,tuned_top_speed,max_fuel_cells,max_load,lemon,image_path FROM simulator_vehicles ORDER BY name')->fetchAll();foreach($rows as &$row){foreach(['mpg_below_35','mpg_35_70','mpg_above_70','capacity','top_speed','tuned_top_speed','lemon'] as $key)$row[$key]=(float)$row[$key];foreach(['max_fuel_cells','max_load'] as $key)$row[$key]=(int)$row[$key];}unset($row);return$rows;}
    public function loadCosts():array{$values=$this->settings->all();$defaults=['driver'=>200,'fuel_cell'=>200,'additional_spare'=>200,'cruising_tires'=>0,'cruising_tune'=>50,'tuned_up'=>0,'radio_scanner'=>1,'radar_scanner'=>5,'radar_jammer'=>25,'police_camo'=>50,'thermal_camera'=>25,'redbull_cooler'=>25,'snack'=>20];foreach($defaults as $key=>$default)$defaults[$key]=max(0,(int)($values['simulator_load_'.$key]??$default));return$defaults;}
    public function supportsDeparture(string $value):bool{$departure=DateTimeImmutable::createFromFormat('!Y-m-d\TH:i',$value,new \DateTimeZone('America/New_York'));return$departure!==false&&$departure->format('Y-m-d\TH:i')===$value&&$this->traffic->hasEvidenceForDate($departure);}

