        $state=json_decode((string)$simulation['state'],true,512,JSON_THROW_ON_ERROR);$state['departure_at']??=$simulation['departure_at'];$now=microtime(true);$last=(new DateTimeImmutable($simulation['last_tick_at']))->format('U.u');
