        $clockDelta=$delta+(float)($state['clock_remainder_seconds']??0);$wholeSeconds=(int)floor($clockDelta);$state['clock_remainder_seconds']=$clockDelta-$wholeSeconds;$simulated=(new DateTimeImmutable($simulation['simulated_at']))->modify('+'.$wholeSeconds.' seconds');$status=$simulation['status'];
        $this->advanceFatigue($state,$delta,$id,$simulated,$status);
        if($status==='running'&&!empty($state['roadside_rest'])){$state['vehicle']['current_speed']=0;$state['vehicle']['stopped_seconds']+=$delta;$state['roadside_rest_seconds']=($state['roadside_rest_seconds']??0)+$delta;}
        elseif($status==='running'&&$state['current_segment'])$this->advanceVehicle($state,$delta,$id,$simulated,$status,(int)$simulation['random_seed']);
        $this->promoteNotification($state,$status);$this->save($id,$state,$status,$simulated);$this->pdo->commit();
        }catch(\Throwable $error){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$error;}
    }

