    private function effectiveDrivingSkill(?array $driver):float{if(!$driver)return 0.0;$penalty=array_sum(array_map(static fn(array $item):float=>(float)($item['amount']??0),(array)($driver['redbull_penalties']??[])));$skill=max(0,(float)($driver['driving']??0)-$penalty);$fatigue=(float)($driver['fatigue']??0);if($fatigue>50)$skill*=max(.5,1-($fatigue-50)/100);return max(0,min(100,$skill));}
    private function segmentSpeed(array $state):float{$segment=$state['current_segment']??null;if(!$segment)return 0.0;$trafficStarted=array_key_exists('traffic_started',$segment)?(bool)$segment['traffic_started']:true;$trafficEnd=(float)($segment['traffic_end_elapsed']??$segment['traffic_cap_seconds']??0);$trafficActive=$segment['traffic_speed_cap']!==null&&$segment['traffic_speed_cap']<$segment['cruising_speed']&&$trafficStarted&&$segment['elapsed_seconds']<$trafficEnd;$segmentLimit=(float)$segment['cruising_speed'];if($trafficActive)$segmentLimit=(float)$segment['traffic_speed_cap']*$this->effectiveDrivingSkill($this->role($state,'driver'))/100;$speed=min($this->vehicleSpeedLimit($state['vehicle']),$segmentLimit);$weather=$state['active_weather']??null;if($weather&&$weather['speed_cap']!==null)$speed=min($speed,(float)$weather['speed_cap']);$inventedTraffic=$state['active_invented_traffic']??null;if($inventedTraffic)$speed=min($speed,(float)$inventedTraffic['speed_cap']);$wildlife=$state['active_wildlife_slowdown']??null;if($wildlife)$speed=min($speed,(float)$wildlife['speed_cap']);return max(5,$speed);}
    private function role(array $state,string $role):?array{foreach($state['drivers'] as $driver)if($driver['role']===$role)return$driver;if($role==='copilot'&&!empty($state['driver_copilot']))return$this->role($state,'driver');return null;}
    private function event(string $id,DateTimeImmutable $at,string $type,array $payload=[]):void{$this->pdo->prepare('INSERT INTO simulation_events(simulation_id,simulated_at,type,payload) VALUES (?,?,?,?::jsonb)')->execute([$id,$at->format(DATE_ATOM),$type,json_encode($payload,JSON_THROW_ON_ERROR)]);}
    private function save(string $id,array $state,string $status,DateTimeImmutable $at):void{$finished=in_array($status,['completed','failed'],true)?',finished_at=now()':'';$sql="UPDATE simulations SET state=?::jsonb,status=?,simulated_at=?,updated_at=now(),last_tick_at=now(),version=version+1".$finished.' WHERE id=?';$this->pdo->prepare($sql)->execute([json_encode($state,JSON_THROW_ON_ERROR),$status,$at->format(DATE_ATOM),$id]);}
}
